#[inline]
fn put_u8(out: &mut [u8], off: usize, v: u8) { out[off] = v; }
#[inline]
fn put_u16(out: &mut [u8], off: usize, v: u16) { out[off..off + 2].copy_from_slice(&v.to_le_bytes()); }
#[inline]
fn put_u32(out: &mut [u8], off: usize, v: u32) { out[off..off + 4].copy_from_slice(&v.to_le_bytes()); }
#[inline]
fn put_i32(out: &mut [u8], off: usize, v: i32) { out[off..off + 4].copy_from_slice(&v.to_le_bytes()); }
#[inline]
fn put_f32(out: &mut [u8], off: usize, v: f32) { out[off..off + 4].copy_from_slice(&v.to_le_bytes()); }
#[inline]
fn put_f64(out: &mut [u8], off: usize, v: f64) { out[off..off + 8].copy_from_slice(&v.to_le_bytes()); }
#[inline]
fn get_u8(buf: &[u8], off: usize) -> u8 { buf[off] }
#[inline]
fn get_u16(buf: &[u8], off: usize) -> u16 { u16::from_le_bytes(buf[off..off + 2].try_into().unwrap()) }
#[inline]
fn get_u32(buf: &[u8], off: usize) -> u32 { u32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) }
#[inline]
fn get_i32(buf: &[u8], off: usize) -> i32 { i32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) }
#[inline]
fn get_f32(buf: &[u8], off: usize) -> f32 { f32::from_le_bytes(buf[off..off + 4].try_into().unwrap()) }
#[inline]
fn get_f64(buf: &[u8], off: usize) -> f64 { f64::from_le_bytes(buf[off..off + 8].try_into().unwrap()) }

/// The 16-byte envelope of every message.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Envelope {
    /// Always 0x4D594131 (`MYA1`).
    pub magic: u32,
    /// Protocol version: high byte major, low byte minor (1.0 is 0x0100).
    pub version: u16,
    /// Message kind, one of `KINDS` (1..=12).
    pub kind: u16,
    /// Per-sender sequence number; wraps at 2^32.
    pub seq: u32,
    /// Bytes of body after the 16-byte envelope.
    pub body_bytes: u32,
}

impl Envelope {
    pub const FIXED_END: usize = 16;
    pub fn write(&self, out: &mut [u8], base: usize) -> Result<usize, i32> {
        if base + Self::FIXED_END > out.len() {
            return Err(ERR_OVERSIZE);
        }
        put_u32(out, base + 0, self.magic);
        put_u16(out, base + 4, self.version);
        put_u16(out, base + 6, self.kind);
        put_u32(out, base + 8, self.seq);
        put_u32(out, base + 12, self.body_bytes);
        let mut cur = base + Self::FIXED_END;
        Ok(cur - base)
    }
    pub fn read(buf: &[u8], base: usize) -> Result<(Self, usize), i32> {
        let limit = buf.len();
        Self::read_to(buf, base, limit)
    }
    fn read_to(buf: &[u8], base: usize, limit: usize) -> Result<(Self, usize), i32> {
        if base.checked_add(Self::FIXED_END).map_or(true, |e| e > limit) {
            return Err(ERR_TRUNCATED);
        }
        let magic = get_u32(buf, base + 0);
        let version = get_u16(buf, base + 4);
        let kind = get_u16(buf, base + 6);
        let seq = get_u32(buf, base + 8);
        let body_bytes = get_u32(buf, base + 12);
        let mut cur = base + Self::FIXED_END;
        Ok((Self {
            magic,
            version,
            kind,
            seq,
            body_bytes,
        }, cur - base))
    }
}

impl Envelope {
    /// An envelope for `kind` with this version, `seq` and `body_bytes`.
    pub fn new(kind: u16, seq: u32, body_bytes: u32) -> Envelope {
        Envelope { magic: MAGIC, version: ((VERSION_MAJOR << 8) | VERSION_MINOR) as u16, kind, seq, body_bytes }
    }
}

