/// replace a bus's automation bindings (voiceId = bus index; ADR 0158 §3)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct BusAutomate {
    pub voice_id: u32,
    pub frame_offset: u32,
    pub bindings: Vec<BusAutomateBindings>,
}

impl BusAutomate {
    pub const FIXED_END: usize = 16;
    pub const OPCODE: u16 = 21; // BUS_AUTOMATE
    pub fn write(&self, out: &mut [u8], base: usize) -> Result<usize, i32> {
        if base + Self::FIXED_END > out.len() {
            return Err(ERR_OVERSIZE);
        }
        put_u32(out, base + 12, u32::try_from(self.bindings.len()).map_err(|_| ERR_OVERSIZE)?);
        let mut cur = base + Self::FIXED_END;
        for item in &self.bindings {
            cur += item.write(out, cur)?;
        }
        let total = cur - base;
        if total % 4 != 0 || total / 4 > u16::MAX as usize {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + RecordHead::OPCODE_AT, Self::OPCODE);
        put_u16(out, base + RecordHead::WORDS_AT, (total / 4) as u16);
        put_u32(out, base + RecordHead::VOICE_ID_AT, self.voice_id);
        put_u32(out, base + RecordHead::FRAME_OFFSET_AT, self.frame_offset);
        Ok(cur - base)
    }
    pub fn read(buf: &[u8], base: usize) -> Result<(Self, usize), i32> {
        let (head, _) = RecordHead::read(buf, base)?;
        if head.opcode != Self::OPCODE {
            return Err(ERR_MALFORMED);
        }
        let limit = base + head.words as usize * 4;
        if limit > buf.len() {
            return Err(ERR_TRUNCATED);
        }
        Self::read_to(buf, base, limit)
    }
    fn read_to(buf: &[u8], base: usize, limit: usize) -> Result<(Self, usize), i32> {
        if base.checked_add(Self::FIXED_END).map_or(true, |e| e > limit) {
            return Err(ERR_TRUNCATED);
        }
        let (head, _) = RecordHead::read(buf, base)?;
        let binding_count = get_u32(buf, base + 12);
        let mut cur = base + Self::FIXED_END;
        let count = binding_count as usize;
        if count.checked_mul(8).map_or(true, |n| n > limit - cur) {
            return Err(ERR_TRUNCATED);
        }
        let mut bindings = Vec::with_capacity(count);
        for _ in 0..count {
            let (item, n) = BusAutomateBindings::read_to(buf, cur, limit)?;
            cur += n;
            bindings.push(item);
        }
        if cur > limit {
            return Err(ERR_MALFORMED);
        }
        let cur = limit; // appended words of a newer minor are skipped
        Ok((Self {
            voice_id: head.voice_id,
            frame_offset: head.frame_offset,
            bindings,
        }, cur - base))
    }
}

/// the bed slots and their host buses (ADR 0162 C2); applies on arrival
#[derive(Clone, Debug, Default, PartialEq)]
pub struct BedConfig {
    pub voice_id: u32,
    pub frame_offset: u32,
    /// per bus, the bed slot its voices encode into; 0xFF (BED_SLOT_NONE) is none
    pub bed_slot: Vec<u8>,
    /// per slot, the bus it decodes into before that bus's effects; 0xFFFF (BED_HOST_NONE) is unused
    pub host_bus: Vec<u16>,
}

impl BedConfig {
    pub const FIXED_END: usize = 20;
    pub const OPCODE: u16 = 22; // BED_CONFIG
    pub fn write(&self, out: &mut [u8], base: usize) -> Result<usize, i32> {
        if base + Self::FIXED_END > out.len() {
            return Err(ERR_OVERSIZE);
        }
        put_u32(out, base + 12, u32::try_from(self.bed_slot.len()).map_err(|_| ERR_OVERSIZE)?);
        if self.host_bus.len() > 4 {
            return Err(ERR_OVERSIZE);
        }
        put_u32(out, base + 16, u32::try_from(self.host_bus.len()).map_err(|_| ERR_OVERSIZE)?);
        let mut cur = base + Self::FIXED_END;
        let padded = (self.bed_slot.len() * 1 + 3) & !3;
        if cur + padded > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for (i, v) in self.bed_slot.iter().enumerate() {
            put_u8(out, cur + i * 1, *v);
        }
        out[cur + self.bed_slot.len() * 1..cur + padded].fill(0);
        cur += padded;
        let padded = (self.host_bus.len() * 2 + 3) & !3;
        if cur + padded > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for (i, v) in self.host_bus.iter().enumerate() {
            put_u16(out, cur + i * 2, *v);
        }
        out[cur + self.host_bus.len() * 2..cur + padded].fill(0);
        cur += padded;
        let total = cur - base;
        if total % 4 != 0 || total / 4 > u16::MAX as usize {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + RecordHead::OPCODE_AT, Self::OPCODE);
        put_u16(out, base + RecordHead::WORDS_AT, (total / 4) as u16);
        put_u32(out, base + RecordHead::VOICE_ID_AT, self.voice_id);
        put_u32(out, base + RecordHead::FRAME_OFFSET_AT, self.frame_offset);
        Ok(cur - base)
    }
    pub fn read(buf: &[u8], base: usize) -> Result<(Self, usize), i32> {
        let (head, _) = RecordHead::read(buf, base)?;
        if head.opcode != Self::OPCODE {
            return Err(ERR_MALFORMED);
        }
        let limit = base + head.words as usize * 4;
        if limit > buf.len() {
            return Err(ERR_TRUNCATED);
        }
        Self::read_to(buf, base, limit)
    }
    fn read_to(buf: &[u8], base: usize, limit: usize) -> Result<(Self, usize), i32> {
        if base.checked_add(Self::FIXED_END).map_or(true, |e| e > limit) {
            return Err(ERR_TRUNCATED);
        }
        let (head, _) = RecordHead::read(buf, base)?;
        let bus_count = get_u32(buf, base + 12);
        let slot_count = get_u32(buf, base + 16);
        let mut cur = base + Self::FIXED_END;
        let padded = (bus_count as usize).checked_mul(1).and_then(|n| n.checked_add(3)).map(|n| n & !3).ok_or(ERR_TRUNCATED)?;
        if padded > limit - cur {
            return Err(ERR_TRUNCATED);
        }
        let mut bed_slot = Vec::with_capacity(bus_count as usize);
        for i in 0..bus_count as usize {
            bed_slot.push(get_u8(buf, cur + i * 1));
        }
        cur += padded;
        if slot_count as usize > 4 {
            return Err(ERR_MALFORMED);
        }
        let padded = (slot_count as usize).checked_mul(2).and_then(|n| n.checked_add(3)).map(|n| n & !3).ok_or(ERR_TRUNCATED)?;
        if padded > limit - cur {
            return Err(ERR_TRUNCATED);
        }
        let mut host_bus = Vec::with_capacity(slot_count as usize);
        for i in 0..slot_count as usize {
            host_bus.push(get_u16(buf, cur + i * 2));
        }
        cur += padded;
        if cur > limit {
            return Err(ERR_MALFORMED);
        }
        let cur = limit; // appended words of a newer minor are skipped
        Ok((Self {
            voice_id: head.voice_id,
            frame_offset: head.frame_offset,
            bed_slot,
            host_bus,
        }, cur - base))
    }
}

